<?php require __DIR__.'/includes/bootstrap.php';$slug=preg_replace('/[^a-z0-9-]/','',strtolower($_GET['slug']??''));$stmt=$pdo->prepare('SELECT * FROM guests WHERE slug=? AND is_active=1');$stmt->execute([$slug]);$guest=$stmt->fetch();if(!$guest){http_response_code(404);?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="<?=base_url('assets/invite.css')?>"><title>Invitation not found</title></head><body><main class="not-found"><div class="om">ॐ</div><h1>Invitation not found</h1><p>This invitation link is invalid or no longer active.</p></main></body></html><?php exit;}$pdo->prepare('UPDATE guests SET invitation_views=invitation_views+1,last_viewed_at=NOW() WHERE id=?')->execute([$guest['id']]);$events=$pdo->query('SELECT * FROM wedding_events ORDER BY sort_order,event_date')->fetchAll();$bride=setting('bride_name','मनीषा');$groom=setting('groom_name','आकाश');$weddingDate=setting('wedding_date','2026-10-18 19:00:00');$canonical=base_url('invite/'.$guest['slug']);$title=$guest['name'].', You Are Invited | '.$bride.' & '.$groom;?><!doctype html><html lang="hi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title><?=e($title)?></title><meta name="description" content="<?=e($guest['name'])?>, you are warmly invited to celebrate the wedding of <?=e($bride)?> and <?=e($groom)?> on 18 October 2026."><meta property="og:title" content="<?=e($title)?>"><meta property="og:description" content="A personalized invitation to celebrate with us on 18 October 2026."><meta property="og:type" content="website"><meta property="og:url" content="<?=e($canonical)?>"><meta name="theme-color" content="#6d1728"><link rel="canonical" href="<?=e($canonical)?>"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@400;500;600;700&family=Noto+Serif+Devanagari:wght@400;500;600;700&family=Manrope:wght@400;500;600&display=swap" rel="stylesheet"><link rel="stylesheet" href="<?=base_url('assets/invite.css')?>"></head><body><div class="grain"></div><button class="music" id="musicToggle" hidden aria-label="Toggle music">♪</button><header class="hero"><div class="corner tl"></div><div class="corner tr"></div><div class="hero-inner reveal"><div class="ganesh">ॐ श्री गणेशाय नमः</div><p class="kicker">TOGETHER WITH THEIR FAMILIES</p><h1><span><?=e($bride)?></span><i>&</i><span><?=e($groom)?></span></h1><p class="invite-line">are delighted to invite</p><div class="guest-name"><?=e($guest['name'])?></div><p>to celebrate their wedding</p><div class="date-lockup"><b>18</b><span>रविवार<br>अक्टूबर</span><b>2026</b></div><p class="venue-short">मंगलम् पैलेस · कोटद्वार</p><a class="seal" href="#greeting">View<br>Invitation</a></div><div class="scroll">SCROLL TO CELEBRATE <span>↓</span></div></header><main><section class="greeting section" id="greeting"><div class="reveal narrow"><span class="section-label">A PERSONAL NOTE</span><h2>प्रिय <?=e($guest['name'])?>,</h2><p class="lead"><?=e($guest['personal_message'] ?: setting('family_message'))?></p><div class="signature">With love,<br><b>The Gusain & Rawat Families</b></div></div></section><section class="couple section"><span class="section-label">THE HAPPY COUPLE</span><div class="couple-grid reveal"><article><span>THE BRIDE</span><h2><?=e($bride)?></h2><p><?=e(setting('bride_details'))?></p></article><div class="amp">&</div><article><span>THE GROOM</span><h2><?=e($groom)?></h2><p><?=e(setting('groom_details'))?></p></article></div></section><section class="events section"><div class="section-heading reveal"><span class="section-label">JOIN THE CELEBRATION</span><h2>वैवाहिक कार्यक्रम</h2><p>Four days of blessings, laughter and cherished traditions</p></div><div class="event-grid"><?php foreach($events as $i=>$event):?><