=csrf_field()?><input type="hidden" name="slug" value="<?=e($guest['slug'])?>"><div class="rsvp-options"><label><input type="radio" name="status" value="attending" required <?=$guest['rsvp_status']==='attending'?'checked':''?>><span>Joyfully attending</span></label><label><input type="radio" name="status" value="maybe" <?=$guest['rsvp_status']==='maybe'?'checked':''?>><span>Maybe</span></label><label><input type="radio" name="status" value="declined" <?=$guest['rsvp_status']==='declined'?'checked':''?>><span>Unable to attend</span></label></div><label>Number of guests<input type="number" name="guests" min="1" max="20" value="<?=e((string)($guest['rsvp_guests']?:1))?>"></label><label>A message for the couple<textarea name="message" maxlength="1000" rows="3"><?=e($guest['rsvp_message'])?></textarea></label><button class="button maroon">Send RSVP</button><p class="form-result" role="status"></p></form></div></section><section class="share section"><div class="reveal"><span class="section-label">SPREAD THE JOY</span><h2>Share this invitation</h2><p>Keep your personalized invitation close or share it with your family.</p><div class="share-buttons"><button class="button maroon" id="shareBtn">Share Invitation</button><a class="button whatsapp" target="_blank" href="https://wa.me/?text=<?=rawurlencode('Hi '.$guest['name'].', you are warmly invited to our wedding celebration. Please find your personalized invitation here: '.$canonical)?>">WhatsApp</a><button class="button outline" data-copy="<?=e($canonical)?>">Copy Link</button></div></div></section></main><footer><div>म <span>♥</span> आ</div><p>18 · 10 · 2026</p><small>Made with love for <?=e($guest['name'])?></small></footer><script>window.invitation={name:<?=json_encode($guest['name'],JSON_UNESCAPED_UNICODE)?>,url:<?=json_encode($canonical)?>,shareText:<?=json_encode('You are warmly invited to the wedding of '.$bride.' & '.$groom,JSON_UNESCAPED_UNICODE)?>};</script><script src="<?=base_url('assets/invite.js')?>"></script></body></html>

